        createInline("IMG").setEmpty();
        createInline("BR").setEmpty();
        createInline("MAP"); // map is defined as inline, but can hold block (what?) or area. Seldom used so NBD.
        createInline("Q");
        createInline("SUB");
        createInline("SUP");
        createInline("SPAN");
        createInline("BDO");

