            ancestors = new ArrayList<Tag>(tagNames.length);
            for (String name : tagNames) {
                ancestors.add(Tag.valueOf(name));
            }
        }
        return this;
    }

    private Tag setParent(String tagName) {
        parent = Tag.valueOf(tagName);
        setAncestor(tagName);
        return this;
    }
